fn extract_hook(call_expr: &CallExpr, component: &mut Component) {
    match &call_expr.callee {
        Expr::Ident(callee) => {
            let hook_name = &callee.sym.to_string();
            match &component.imported_hook_metadata {
                Some(imported_hooks) => {
                    if imported_hooks.contains_key(hook_name) {
                        println!("[Custom Hook] Found imported hook call: {}", hook_name);
                        Self::extract_custom_hook_call(call_expr, component, hook_name);
                        return;
                    }
                }
                _ => {}
            }
            match hook_name.as_str() {
                "useState" => {
                    Self::extract_use_state(call_expr, component, "useState")
                }
                "useClientState" => {
                    Self::extract_use_state(call_expr, component, "useClientState")
                }
                "useProtectedState" => {
                    Self::extract_use_protected_state(call_expr, component)
                }
                "useStateX" => {
                    extract_use_state_x(call_expr, component)
                }
                "useEffect" => {
                    Self::extract_use_effect(call_expr, component)
                }
                "useRef" => {
                    Self::extract_use_ref(call_expr, component)
                }
                "useMarkdown" => {
                    Self::extract_use_markdown(call_expr, component)
                }
                "useRazorMarkdown" => {
                    Self::extract_use_razor_markdown(call_expr, component)
                }
                "useTemplate" => {
                    Self::extract_use_template(call_expr, component)
                }
                "useValidation" => {
                    Self::extract_use_validation(call_expr, component)
                }
                "useModal" => {
                    Self::extract_use_modal(call_expr, component)
                }
                "useToggle" => {
                    Self::extract_use_toggle(call_expr, component)
                }
                "useDropdown" => {
                    Self::extract_use_dropdown(call_expr, component)
                }
                "usePub" => {
                    Self::extract_use_pub(call_expr, component)
                }
                "useSub" => {
                    Self::extract_use_sub(call_expr, component)
                }
                "useMicroTask" => {
                    Self::extract_use_micro_task(call_expr, component)
                }
                "useMacroTask" => {
                    Self::extract_use_macro_task(call_expr, component)
                }
                "useSignalR" => {
                    Self::extract_use_signal_r(call_expr, component)
                }
                "usePredictHint" => {
                    Self::extract_use_predict_hint(call_expr, component)
                }
                "useServerTask" => {
                    Self::extract_use_server_task(call_expr, component)
                }
                "usePaginatedServerTask" => {
                    Self::extract_use_paginated_server_task(call_expr, component)
                }
                "useMvcState" => {
                    Self::extract_use_mvc_state(call_expr, component)
                }
                "useMvcViewModel" => {
                    Self::extract_use_mvc_view_model(call_expr, component)
                }
                _ => {
                    {
                        if hook_name.starts_with("use") {
                            Self::extract_custom_hook_call(call_expr, component, hook_name)
                        }
                    }
                }
            }
        }
        _ => {}
    }
}

fn extract_use_state(call_expr: &CallExpr, parent: &VarDeclarator, component: &mut Component, hook_type: &str) {
    match &parent.name {
        Pat::Array(array_pattern) => {
            let elements = &array_pattern.elems;
            if elements.is_empty() {
                return;
            }
            let state_var = elements.get(0);
            let setter_var = if (elements.len() > 1) {
                elements.get(1)
            } else {
                None
            };
            if state_var.is_none() {
                println!("[useState] Skipping invalid destructuring (no state variable)");
                return;
            }
            let state_name = if state_var {
                id.name.to_string()
            } else {
                return;
            };
            let setter_name = if setter_var {
                Some(id.name.to_string())
            } else {
                None
            };
            let initial_value = call_expr.args.get(0);
            let explicit_type = if &call_expr.type_parameters {
                match type_params.params.get(0) {
                    Some(type_param) => {
                        let csharp_type = ts_type_to_csharp_type(type_param);
                        println!("[useState] Found explicit type parameter for '{}': {}", state_name, csharp_type);
                        Some(csharp_type)
                    }
                    _ => {
                        None
                    }
                }
            } else {
                None
            };
            let initial_value_expr = if initial_value {
                generate_csharp_expression(init)
            } else {
                "null".into()
            };
            let state_type = if explicit_type {
                explicit
            } else {
                if initial_value {
                    infer_type(init)
                } else {
                    "object".into()
                }
            };
            let state_info = UseStateInfo { name: state_name.clone(), setter: setter_name, initial_value: initial_value_expr, state_type: state_type };
            if (hook_type == "useState") {
                component.use_state.push(state_info);
                component.state_types.insert(state_name.clone(), "server".into())
            } else {
                component.use_client_state.push(state_info);
                component.state_types.insert(state_name.clone(), "client".into())
            }
        }
        _ => {}
    }
}

