fn extract_use_effect(call_expr: &CallExpr, component: &mut Component) {
    let callback = call_expr.args.get(0);
    let dependencies = call_expr.args.get(1);
    component.use_effect.push(UseEffectInfo { body: callback.cloned(), dependencies: dependencies.cloned() });
    match callback {
        Some(cb) => {
            let effect_index = component.client_effects.len();
            let hook_calls = analyze_hook_usage(cb);
            let transformed = transform_effect_callback(cb, &hook_calls);
            let js_code = codegen::generate(&transformed);
            component.client_effects.push(ClientEffect { name: format!("Effect_{}", effect_index), js_code: js_code, dependencies: dependencies.cloned(), hook_calls: hook_calls })
        }
        _ => {}
    }
}

