fn extract_use_server_task(call_expr: &CallExpr, parent: &VarDeclarator, component: &mut Component) {
    match &parent.name {
        Pat::Ident(id) => {
            let task_name = match id {
                Pat::Ident(inner) => {
                    inner
                }
                _ => {
                    unreachable!()
                }
            }.sym.to_string();
            let async_function_arg = call_expr.args.get(0);
            let options_arg = call_expr.args.get(1);
            let (is_async, is_generator, params_list, function_body) = match async_function_arg {
                Some(Expr::Arrow(arrow)) => {
                    {
                        (arrow.is_async, arrow.is_generator, arrow.params.clone(), arrow.body.clone())
                    }
                }
                Some(Expr::Fn(func)) => {
                    {
                        (func.is_async, func.is_generator, func.params.clone(), func.body.clone())
                    }
                }
                _ => {
                    {
                        println!("[useServerTask] First argument must be an async function");
                        return;
                    }
                }
            };
            if !is_async {
                println!("[useServerTask] Function must be async");
                return;
            }
            let mut is_streaming = is_generator;
            let mut parameters = vec![];
            for param in params_list {
                match param {
                    Pat::Ident(id) => {
                        parameters.push(ServerTaskParameter { name: id.sym.to_string().clone(), param_type: "object".into() })
                    }
                    _ => {}
                }
            }
            let mut estimated_chunks = None;
            let mut runtime = "csharp".into();
            let mut parallel = false;
            match options_arg {
                Some(Expr::Object(obj)) => {
                    for prop in &obj.properties {
                        match prop {
                            ObjectProperty::Property(p) => {
                                match &p.key {
                                    Expr::Ident(key) => {
                                        match key.sym.to_string().as_str() {
                                            "stream" => {
                                                {
                                                    match &p.value {
                                                        Lit::Bool(b) => {
                                                            is_streaming = b.value
                                                        }
                                                        _ => {}
                                                    }
                                                }
                                            }
                                            "estimatedChunks" => {
                                                {
                                                    match &p.value {
                                                        Lit::Num(num) => {
                                                            estimated_chunks = Some(num.value)
                                                        }
                                                        _ => {}
                                                    }
                                                }
                                            }
                                            "runtime" => {
                                                {
                                                    match &p.value {
                                                        Lit::Str(s) => {
                                                            runtime = String::from_utf8_lossy(s.value.as_bytes())
                                                        }
                                                        _ => {}
                                                    }
                                                }
                                            }
                                            "parallel" => {
                                                {
                                                    match &p.value {
                                                        Lit::Bool(b) => {
                                                            parallel = b.value
                                                        }
                                                        _ => {}
                                                    }
                                                }
                                            }
                                            _ => {
                                                {
                                                }
                                            }
                                        }
                                    }
                                    _ => {}
                                }
                            }
                            _ => {}
                        }
                    }
                }
                _ => {}
            }
            component.use_server_task.push(UseServerTaskInfo { name: task_name, async_function: async_function_arg.cloned(), parameters: parameters, is_streaming: is_streaming, estimated_chunks: estimated_chunks, return_type: "object".into(), runtime: runtime, parallel: parallel })
        }
        _ => {}
    }
}

